import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def count_divisors(n):
    return len(get_divisors(n))

results = []

# Check all n such that n < 100 and tau(n) >= 5
for n in range(1, 100):
    tau_n = count_divisors(n)

    if tau_n >= 5:
        divisors = get_divisors(n)

        # Since tau_n >= 5, we are guaranteed to have at least 5 divisors.
        # Smallest divisors are indexed 0, 1, 2, 3, 4...

        # a is the second smallest divisor (index 1)
        a = divisors[1]
        # b is the third smallest divisor (index 2)
        b = divisors[2]
        # c is the fifth smallest divisor (index 4)
        c = divisors[4]

        # Check the condition: ab + ac + bc = n
        condition = (a * b) + (a * c) + (b * c)

        if condition == n:
            results.append(tau_n)

print(f"Values of tau(n) found: {sorted(list(set(results)))}")
